package dev.buildcli.plugin.roof;
import dev.buildcli.plugin.BuildCLICommandPlugin;
import picocli.CommandLine;
import picocli.CommandLine.Command;
import picocli.CommandLine.Parameters;
import picocli.CommandLine.Option;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.util.concurrent.Callable;

/** Generated by BuildCLI plugin init, extended with the Roofline API workflow. */
@Command(name="roof", description="Roof measurements, estimates and proposal exports.", mixinStandardHelpOptions=true,
  subcommands={RoofCommand.Health.class, RoofCommand.Connectors.class, RoofCommand.Geocode.class,
    RoofCommand.SandboxAddresses.class, RoofCommand.SandboxRequest.class, RoofCommand.SandboxResult.class, RoofCommand.SandboxSelect.class, RoofCommand.Report.class, RoofCommand.Import.class, RoofCommand.Estimate.class,
    RoofCommand.Quote.class, RoofCommand.Quotes.class, RoofCommand.Export.class})
public class RoofCommand extends BuildCLICommandPlugin {
  @Override public void run(){ new CommandLine(this).usage(System.out); }
  @Override public String version(){ return "1.0.0"; }
  @Override public String name(){ return "roof"; }
  @Override public String description(){ return "Roofline roofing estimator"; }
  static String escape(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
  static HttpResponse<byte[]> request(String path, String body, boolean auth) throws Exception {
    URI base=URI.create(System.getenv().getOrDefault("ROOFLINE_URL","http://127.0.0.1:4311"));
    if(base.getUserInfo()!=null || !("https".equals(base.getScheme()) || ("http".equals(base.getScheme()) && ("localhost".equals(base.getHost()) || "127.0.0.1".equals(base.getHost()) || "[::1]".equals(base.getHost()))))) throw new IllegalArgumentException("Use HTTPS for remote servers, or HTTP on loopback, without credentials in URL.");
    var builder=HttpRequest.newBuilder(base.resolve("/api"+path)).timeout(Duration.ofSeconds(30)).header("Content-Type","application/json");
    if(auth){String token=System.getenv("ROOFLINE_TOKEN");if(token==null||token.isBlank())throw new IllegalArgumentException("Set ROOFLINE_TOKEN to the server API_TOKEN.");builder.header("Authorization","Bearer "+token);}
    if(body==null)builder.GET();else builder.POST(HttpRequest.BodyPublishers.ofString(body));
    var result=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).followRedirects(HttpClient.Redirect.NEVER).build().send(builder.build(),HttpResponse.BodyHandlers.ofByteArray());
    if(result.statusCode()<200||result.statusCode()>=300)throw new IllegalStateException("HTTP "+result.statusCode()+": "+new String(result.body(),StandardCharsets.UTF_8));
    return result;
  }
  static abstract class ApiCommand implements Callable<Integer> {
    abstract void execute() throws Exception;
    @Override public Integer call(){try{execute();return 0;}catch(Exception e){System.err.println("Roofline: "+e.getMessage());return 1;}}
    void print(String path,String body,boolean auth)throws Exception{System.out.println(new String(request(path,body,auth).body(),StandardCharsets.UTF_8));}
  }
  @Command(name="health",description="Check server health",mixinStandardHelpOptions=true)
  public static class Health extends ApiCommand{void execute()throws Exception{print("/health",null,false);}}
  @Command(name="connectors",description="Inspect configured connectors",mixinStandardHelpOptions=true)
  public static class Connectors extends ApiCommand{void execute()throws Exception{print("/connectors",null,true);}}
  @Command(name="geocode",description="Find a US property with Google Maps",mixinStandardHelpOptions=true)
  public static class Geocode extends ApiCommand{@Parameters(index="0",description="Full US address")String address;void execute()throws Exception{print("/lookup/geocode","{\"address\":"+escape(address)+"}",true);}}
  @Command(name="sandbox-addresses",description="List EagleView Omaha sandbox addresses",mixinStandardHelpOptions=true)
  public static class SandboxAddresses extends ApiCommand{void execute()throws Exception{print("/sandbox/properties",null,true);}}
  @Command(name="sandbox-request",description="Request sandbox roof data",mixinStandardHelpOptions=true)
  public static class SandboxRequest extends ApiCommand{@Parameters(index="0")String address;void execute()throws Exception{print("/sandbox/requests","{\"address\":"+escape(address)+"}",true);}}
  @Command(name="sandbox-result",description="Check a sandbox request",mixinStandardHelpOptions=true)
  public static class SandboxResult extends ApiCommand{@Parameters(index="0")java.util.UUID id;void execute()throws Exception{print("/sandbox/requests/"+id,null,true);}}
  @Command(name="sandbox-select",description="Import a sandbox structure by zero-based index",mixinStandardHelpOptions=true)
  public static class SandboxSelect extends ApiCommand{@Parameters(index="0")java.util.UUID id;@Parameters(index="1")int index;void execute()throws Exception{print("/sandbox/requests/"+id+"/select","{\"index\":"+index+"}",true);}}
  @Command(name="report",description="Retrieve a completed EagleView report",mixinStandardHelpOptions=true)
  public static class Report extends ApiCommand{@Parameters(index="0")String id;void execute()throws Exception{if(!id.matches("\\d{1,15}"))throw new IllegalArgumentException("Numeric report ID required.");print("/lookup/eagleview","{\"reportId\":"+escape(id)+"}",true);}}
  @Command(name="import",description="Import a normalized JSON measurement",mixinStandardHelpOptions=true)
  public static class Import extends ApiCommand{@Option(names="--file",required=true)Path file;void execute()throws Exception{String json=Files.readString(file).trim();if(!json.startsWith("{")||!json.endsWith("}"))throw new IllegalArgumentException("JSON object required.");print("/measurements",json.substring(0,json.length()-1)+",\"source\":\"import\"}",true);}}
  @Command(name="estimate",description="Calculate scope JSON with the company pricebook",mixinStandardHelpOptions=true)
  public static class Estimate extends ApiCommand{@Option(names="--file",required=true)Path file;void execute()throws Exception{print("/estimate",Files.readString(file),true);}}
  @Command(name="quote",description="Save a draft proposal from request JSON",mixinStandardHelpOptions=true)
  public static class Quote extends ApiCommand{@Option(names="--file",required=true)Path file;void execute()throws Exception{print("/quotes",Files.readString(file),true);}}
  @Command(name="quotes",description="List persisted proposals",mixinStandardHelpOptions=true)
  public static class Quotes extends ApiCommand{void execute()throws Exception{print("/quotes",null,true);}}
  @Command(name="export",description="Download a PDF without overwriting an existing file",mixinStandardHelpOptions=true)
  public static class Export extends ApiCommand{@Parameters(index="0")String id;@Option(names="--out",required=true)Path out;void execute()throws Exception{if(!id.matches("[a-zA-Z0-9-]+"))throw new IllegalArgumentException("Invalid quote ID.");Files.write(out,request("/quotes/"+id+"/pdf",null,true).body(),StandardOpenOption.CREATE_NEW);System.out.println("Saved "+out);}}
}
